def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two non-overlapping
    paths from the top-left corner to the bottom-right corner of an N x N grid.
    Paths may move only rightward or downward. Each cell's value can be counted
    at most once even if visited by both paths.
    """
    try:
        if not isinstance(N, int) or N <= 0:
            return 0

        # Build the grid with 1-based indexing
        grid = [[0] * (N + 1) for _ in range(N + 1)]
        for x, y, val in grid_values:
            if x == 0 and y == 0 and val == 0:
                break
            if 1 <= x <= N and 1 <= y <= N:
                grid[x][y] = val
        # Dynamic programming: dp[i1][i2] is max sum when
        # walkers are at (i1, j1) and (i2, j2) respectively,
        # where j1 = k - i1, j2 = k - i2, and k = i1 + j1 = i2 + j2.
        # We only need the previous step's values.
        INF_NEG = -10**9
        dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        dp_prev[1][1] = 0  # both start at (1,1) with no value collected

        for k in range(2, 2 * N + 1):
            dp_curr = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
            for i1 in range(1, N + 1):
                j1 = k - i1
                if j1 < 1 or j1 > N:
                    continue
                for i2 in range(1, N + 1):
                    j2 = k - i2
                    if j2 < 1 or j2 > N:
                        continue
                    best = INF_NEG
                    # Consider all combinations of moves: up or left for each walker
                    for pi1 in (i1 - 1, i1):
                        for pi2 in (i2 - 1, i2):
                            if pi1 < 1 or pi2 < 1:
                                continue
                            if dp_prev[pi1][pi2] == INF_NEG:
                                continue
                            candidate = dp_prev[pi1][pi2]
                            val1 = grid[i1][j1]
                            val2 = grid[i2][j2]
                            if i1 == i2 and j1 == j2:
                                candidate += val1
                            else:
                                candidate += val1 + val2
                            if candidate > best:
                                best = candidate
                    dp_curr[i1][i2] = best
            dp_prev = dp_curr

        return dp_prev[N][N] if dp_prev[N][N] != INF_NEG else 0
    except Exception:
        # In case of unforeseen runtime issues, return 0 as safe output
        return 0

