        if N == 0:
            return 0
        if K < 0:
            return 0
        # Cannot place more than N-1 multiplication signs
        if K > N - 1:
            return 0
    except Exception:
        return 0

    # If no cuts required, return the numeric value of the whole string
    if K == 0:
        try:
            return int(num_str)
        except Exception:
            return 0

    # dp[k][i] will store the maximum product for the first i digits
    # using exactly k cuts (i.e., k+1 segments).
    # We only need two rows at a time but clarity prefers full table.
    dp = [[-1] * (N + 1) for _ in range(K + 1)]

    # Base case: 0 cuts -> one segment (whole prefix)
    for i in range(1, N + 1):
        try:
            dp[0][i] = int(num_str[:i])
        except Exception:
            dp[0][i] = 0

    # Fill DP table
    for k in range(1, K + 1):
        # At least k+1 digits are needed to make k cuts
        for i in range(k + 1, N + 1):
            best = -1
            # last cut between j-1 and j, last segment is num_str[j:i]
            # j must be >= k because we need k-1 cuts in the first j digits
