def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize student chatting.
    """
    # Helper to generate combinations of list elements of length r
    def combos(lst, r):
        res = []
        def back(start, path):
            if len(path) == r:
                res.append(tuple(path))
                return
            if start >= len(lst):
                return
            for i in range(start, len(lst)):
                path.append(lst[i])
                back(i + 1, path)
                path.pop()
        back(0, [])
        return res

    # Possible aisle positions (between rows/columns)
    row_positions = list(range(1, M))   # aisle between i and i+1
    col_positions = list(range(1, N))   # aisle between j and j+1

    # Precompute which pairs each aisle can separate
    row_separated = {}
    for r in row_positions:
        separated_set = set()
        for idx, (x, y, p, q) in enumerate(chatting_pairs):
            r1, r2 = (x, p) if x <= p else (p, x)
            if r1 <= r < r2:
                separated_set.add(idx)
        row_separated[r] = separated_set

    col_separated = {}
    for c in col_positions:
        separated_set = set()
        for idx, (x, y, p, q) in enumerate(chatting_pairs):
            c1, c2 = (y, q) if y <= q else (q, y)
            if c1 <= c < c2:
                separated_set.add(idx)
        col_separated[c] = separated_set

    # Limit number of aisles to available positions
    k = min(K, len(row_positions))
    l = min(L, len(col_positions))

    best_row_combo = ()
    best_col_combo = ()
    best_count = -1

    row_combos = combos(row_positions, k)
    col_combos = combos(col_positions, l)

    for rcomb in row_combos:
        for ccomb in col_combos:
            covered = set()
            for r in rcomb:
                covered.update(row_separated[r])
            for c in ccomb:
                covered.update(col_separated[c])
            cnt = len(covered)
            if cnt > best_count:
                best_count = cnt
                best_row_combo = rcomb
                best_col_combo = ccomb
            elif cnt == best_count:
                if rcomb < best_row_combo or (rcomb == best_row_combo and ccomb < best_col_combo):
                    best_row_combo = rcomb
                    best_col_combo = ccomb

    row_str = " ".join(str(r) for r in best_row_combo) if best_row_combo else ""
    col_str = " ".join(str(c) for c in best_col_combo) if best_col_combo else ""
    return (row_str, col_str)

def max_happiness(n: int, m: int, items: list) -> int:
    """
    Calculate the maximum total importance value achievable within a given budget.

    Args:
        n (int): Total budget available for purchasing items.
        m (int): Number of items available for selection.
        items (list of tuple[int, int]): Each tuple contains (price, importance).

    Returns:
        int: Maximum total importance value within the budget.
    """
    # Basic input validation
    try:
        if not isinstance(n, int) or not isinstance(m, int):
            return 0
        if n < 0 or m < 0:
            return 0
        if not isinstance(items, list):
            return 0
        if len(items) != m:
            return 0
        for price, importance in items:
            if not isinstance(price, int) or not isinstance(importance, int):
                raise ValueError
            if price < 0 or importance < 0:
                raise ValueError
    except Exception:
        return 0

    # Dynamic programming for 0-1 knapsack
    dp = [0] * (n + 1)
    for price, importance in items:
        value = price * importance
        for w in range(n, price - 1, -1):
            new_val = dp[w - price] + value
            if new_val > dp[w]:
                dp[w] = new_val
    return dp[n]

def polynomial_to_string(n: int, coeffs: list) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer.")
    if not isinstance(coeffs, list):
        raise ValueError("coeffs must be a list.")
    expected_len = n + 1
    if len(coeffs) != expected_len:
        raise ValueError(f"coeffs length must be {expected_len} (n+1).")
    terms = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and deg != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        if deg == 0:
            var_str = ''
        elif deg == 1:
            var_str = 'x'
        else:
            var_str = f'x^{deg}'
        term_body = coeff_str + var_str
        if not terms:
            if sign == '-':
                term_body = '-' + term_body
            # positive first term has no leading '+'
        else:
            term_body = sign + term_body
        terms.append(term_body)
    return ''.join(terms) if terms else '0'

def select_volunteers(n: int, m: int, applicants: list) -> tuple:
    """
    Selects and determines the interview score cutoff and the list of applicants who qualify for the interview process.

    Args:
    - n (int): The total number of applicants.
    - m (int): The planned number of volunteers to be recruited.
    - applicants (List[Tuple[int, int]]): A list of tuples where each tuple contains the registration number and test score of an applicant.

    Returns:
    - Tuple[int, List[Tuple[int, int]]]: A tuple containing the interview score cutoff and a list of tuples, each of which includes
      the registration number and test score of qualified applicants.
    """
    # Validate input types
    if not isinstance(n, int) or not isinstance(m, int) or n < 0 or m < 0:
        raise ValueError("n and m must be non-negative integers")
    if not isinstance(applicants, list):
        raise TypeError("applicants must be a list of tuples")
    # Validate applicants content
    for a in applicants:
        if (
            not isinstance(a, tuple)
            or len(a) != 2
            or not isinstance(a[0], int)
            or not isinstance(a[1], (int, float))
        ):
            raise TypeError(
                "Each applicant must be a tuple of (registration_number:int, score:int|float)"
            )
    if n == 0 or m == 0 or not applicants:
        return (0, [])

    # Sort applicants by score descending, then registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine cutoff index (150% of planned recruits, rounded down)
    cutoff_index = int(1.5 * m)  # floor because int truncates
    if cutoff_index <= 0:
        # No cutoff possible
        return (0, [])

    # Determine cutoff score
    if cutoff_index > len(sorted_applicants):
        cutoff_score = sorted_applicants[-1][1]
    else:
        cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Filter qualified applicants
    qualified = [app for app in sorted_applicants if app[1] >= cutoff_score]
    return (cutoff_score, qualified)

