    if len(encoded) != len(original):
        return "Failed"
    # Build mapping
    mapping: dict[str, str] = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradictory mapping
        else:
            mapping[e_char] = o_char
    # Ensure mapping covers all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"
    # Decode message
    decoded = []
    for char in message:
        if char not in mapping:
            return "Failed"  # message contains unknown character
        decoded.append(mapping[char])
    return "".join(decoded)

