def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs a binary tree from its inorder and postorder traversals and returns
    the preorder traversal as a string.

    Raises:
        ValueError: If the input strings are incompatible (different lengths,
        differing character sets, or duplicate characters).
    """
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must have the same length.")
    if len(inorder) == 0:
        return ""
    if len(set(inorder)) != len(inorder):
        raise ValueError("Inorder string contains duplicate characters.")
    if len(set(postorder)) != len(postorder):
        raise ValueError("Postorder string contains duplicate characters.")
    if sorted(inorder) != sorted(postorder):
        raise ValueError("Inorder and postorder strings must contain the same characters.")

    def build_pre(in_in: str, post_in: str) -> str:
        if not in_in:
            return ""
        root = post_in[-1]
        idx = in_in.index(root)
        left_in = in_in[:idx]
        right_in = in_in[idx+1:]
        left_post = post_in[:len(left_in)]
        right_post = post_in[len(left_in):-1]
        return root + build_pre(left_in, left_post) + build_pre(right_in, right_post)

    return build_pre(inorder, postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.

    Args:
        inorder (str): The inorder traversal of the binary tree.
        postorder (str): The postorder traversal of the binary tree.

    Returns:
        str: The preorder traversal of the binary tree.

    The function validates that the inputs are non‑empty strings of equal length
    and that each character in the traversals is unique.  If the input is
    invalid or the tree cannot be reconstructed, an empty string is returned.
    """
    try:
        if not isinstance(inorder, str) or not isinstance(postorder, str):
            return ""
        if len(inorder) != len(postorder):
            return ""
        n = len(inorder)
        if n == 0:
            return ""

        # Ensure all characters are unique; otherwise reconstruction is ambiguous
        if len(set(inorder)) != n or len(set(postorder)) != n:
            return ""

        # Build a map from node value to its index in inorder for O(1) lookups
        in_index = {ch: i for i, ch in enumerate(inorder)}

        def helper(i_start: int, i_end: int, p_start: int, p_end: int) -> str:
            if i_start > i_end:
                return ""
            if i_start == i_end:
                return inorder[i_start]
            root = postorder[p_end]
            idx = in_index.get(root)
            if idx is None or idx < i_start or idx > i_end:
                raise ValueError("Traversal sequences do not correspond to a valid tree")

            left_len = idx - i_start
            left_pre = helper(i_start, idx - 1, p_start, p_start + left_len - 1)
            right_pre = helper(idx + 1, i_end, p_start + left_len, p_end - 1)
            return root + left_pre + right_pre

        return helper(0, n - 1, 0, n - 1)
    except Exception:
        return ""

