    Perform string transformation from A to B using a set of transformation rules.

    BFS algorithm exploring transformations up to 10 steps. Return minimal steps or "NO ANSWER!".
    """
    if A == B:
        return 0

    max_steps = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_steps:
            continue

        for src, tgt in rules:
            if not src:          # skip empty source pattern
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
