                else:
                    return True  # unrecognised predicate, ignore
                return claim_is_true
            # Unrecognized pattern: ignore
            return True
        for speaker, stmts in statements.items():
            speaker_norm = speaker.upper()
            is_liar = speaker_norm in liar_count
            for st in stmts:
